using System; using System.Collections.Generic; using System.Threading; using System.Threading.Tasks; using Xunit; using AlKhayal.Application.Authentication; using AlKhayal.Data.Authentication;
namespace AlKhayal.UnitTests
{
    public sealed class AuthenticationTests
    {
        [Fact] public void Password_hash_is_salted_and_verifies(){var h=new PasswordHasher();var a=h.Hash("secret");var b=h.Hash("secret");Assert.NotEqual(a,b);Assert.True(h.Verify("secret",a));Assert.False(h.Verify("wrong",a));}
        [Fact] public async Task Login_distinguishes_unknown_invalid_and_disabled_accounts(){var hasher=new PasswordHasher();var users=new MemoryUsers(new UserRecord{Id=1,Username="active",DisplayName="نشط",Role="operator",PasswordHash=hasher.Hash("secret"),IsActive=true},new UserRecord{Id=2,Username="disabled",DisplayName="موقوف",Role="operator",PasswordHash=hasher.Hash("secret"),IsActive=false});var service=new AuthService(users,new MemorySessions(),hasher,new FixedTokens(),new FixedClock());Assert.Equal("invalid_credentials",(await service.LoginAsync(new LoginCommand{Username="missing",Password="secret"},CancellationToken.None)).ErrorCode);Assert.Equal("invalid_credentials",(await service.LoginAsync(new LoginCommand{Username="active",Password="wrong"},CancellationToken.None)).ErrorCode);Assert.Equal("disabled_account",(await service.LoginAsync(new LoginCommand{Username="disabled",Password="secret"},CancellationToken.None)).ErrorCode);var success=await service.LoginAsync(new LoginCommand{Username="active",Password="secret"},CancellationToken.None);Assert.True(success.Succeeded);Assert.Equal("نشط",success.User.DisplayName);Assert.False(string.IsNullOrWhiteSpace(success.CsrfToken));}
        private sealed class MemoryUsers:IUserStore{private readonly IDictionary<string,UserRecord> _users=new Dictionary<string,UserRecord>(StringComparer.OrdinalIgnoreCase);public MemoryUsers(params UserRecord[] users){foreach(var user in users)_users[user.Username]=user;}public Task<UserRecord> FindByUsernameAsync(string username,CancellationToken ct){UserRecord value;_users.TryGetValue(username,out value);return Task.FromResult(value);}public Task<long>CreateAsync(string username,string displayName,string hash,string role,CancellationToken ct){throw new NotSupportedException();}public Task UpdatePasswordHashAsync(long userId,string hash,CancellationToken ct){throw new NotSupportedException();}public Task UpdateLastLoginAsync(long userId,DateTime utc,CancellationToken ct){return Task.CompletedTask;}}
        private sealed class MemorySessions:ISessionStore{private readonly IDictionary<string,SessionRecord> _sessions=new Dictionary<string,SessionRecord>();public Task SaveAsync(SessionRecord session,CancellationToken ct){_sessions[session.Token]=session;return Task.CompletedTask;}public Task<SessionRecord> FindAsync(string token,CancellationToken ct){SessionRecord value;_sessions.TryGetValue(token,out value);return Task.FromResult(value);}public Task DeleteAsync(string token,CancellationToken ct){_sessions.Remove(token);return Task.CompletedTask;}}
        private sealed class FixedTokens:ITokenGenerator{private int _number;public string CreateToken(){_number++;return "token-"+_number;}}
        private sealed class FixedClock:IClock{public DateTime UtcNow{get{return new DateTime(2026,10,20,12,0,0,DateTimeKind.Utc);}}}
    }
}
